 public static class Diagnostics994 {
  const int MaxText=32768; const long PerFile=20L*1024*1024, BundleLimit=128L*1024*1024;
  static readonly object gate=new object(); static long sequence,dropped; static string root;
  public static void Initialize(string appRoot){root=Path.GetFullPath(appRoot);AppDomain.CurrentDomain.UnhandledException+=(s,e)=>Record(root,"managed.unhandled","fatal",new{terminating=e.IsTerminating},e.ExceptionObject as Exception);TaskScheduler.UnobservedTaskException+=(s,e)=>Record(root,"managed.unobserved_task","error",null,e.Exception);Record(root,"desktop.started","info",new{revision="R995",pid=Process.GetCurrentProcess().Id,qpc_frequency=Stopwatch.Frequency,os=Environment.OSVersion.VersionString,runtime=Environment.Version.ToString(),is64bit=Environment.Is64BitProcess});}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=32*1024*1024,RecursionLimit=64};}
  public static string Serialize(object value){return Json().Serialize(value);}
  static void Guard(string path){for(var d=new DirectoryInfo(Path.GetFullPath(path));d!=null;d=d.Parent)if(d.Exists&&(d.Attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("Diagnostic path must not contain reparse points");}
  static string Limit(string s){return s==null?null:s.Length<=MaxText?s:s.Substring(0,MaxText)+" [truncated]";}
  public static string Redact(string text,string appRoot){if(text==null)return null;foreach(string path in new[]{appRoot,Environment.GetFolderPath(Environment.SpecialFolder.UserProfile)}){if(String.IsNullOrEmpty(path))continue;string replacement=path==appRoot?"%APP%":"%USERPROFILE%";text=text.Replace(path.Replace("\\","\\\\"),replacement).Replace(path,replacement).Replace(path.Replace('\\','/'),replacement);}return text;}
  public static void Record(string appRoot,string code,string severity,object detail,Exception error=null){
   if(!Monitor.TryEnter(gate)){Interlocked.Increment(ref dropped);return;}try{
    string data=Path.Combine(appRoot,"UserData");Guard(data);Directory.CreateDirectory(data);string file=Path.Combine(data,"desktop-events994.jsonl");
    if(File.Exists(file)&&new FileInfo(file).Length>2*1024*1024){string prev=file+".previous";if(File.Exists(prev)){if((File.GetAttributes(prev)&FileAttributes.ReparsePoint)!=0)throw new IOException("Log link rejected");File.Delete(prev);}File.Move(file,prev);}
    var payload=new{schema=1,revision="R995",sequence=Interlocked.Increment(ref sequence),utc=DateTime.UtcNow.ToString("o"),qpc=Stopwatch.GetTimestamp(),qpc_frequency=Stopwatch.Frequency,pid=Process.GetCurrentProcess().Id,managed_thread=Thread.CurrentThread.ManagedThreadId,code=code,severity=severity,detail=detail,error=error==null?null:new{type=error.GetType().FullName,hresult="0x"+error.HResult.ToString("X8"),message=Limit(error.Message),stack=Limit(error.ToString())},dropped_events=Interlocked.Read(ref dropped)};
    string line=Redact(Serialize(payload),appRoot);if(line.Length>65536)line=Serialize(new{schema=1,code=code,severity=severity,utc=DateTime.UtcNow.ToString("o"),truncated=true,message=Limit(line)});
    using(var output=new FileStream(file,FileMode.Append,FileAccess.Write,FileShare.ReadWrite|FileShare.Delete))using(var w=new StreamWriter(output,new UTF8Encoding(false))){w.WriteLine(line);w.Flush();if(severity=="fatal")output.Flush(true);}
   }catch{Interlocked.Increment(ref dropped);}finally{Monitor.Exit(gate);}
  }
  static string Hash(string path){using(var s=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
  public static object SoftwareIdentity(string appRoot){var files=new List<object>();foreach(var n in new[]{"SmoothMotion.exe","SmoothMotion-Engine.exe","assets988.json","UserData/runtime-work/graph922.bin","UserData/runtime-shaders/native969-down-compiled.spv","UserData/runtime-shaders/native969-warp-compiled.spv"}){string p=Path.Combine(appRoot,n.Replace('/',Path.DirectorySeparatorChar));try{if(File.Exists(p))files.Add(new{name=n,bytes=new FileInfo(p).Length,sha256=Hash(p)});else files.Add(new{name=n,missing=true});}catch(Exception e){files.Add(new{name=n,error=e.GetType().Name,hresult=e.HResult});}}return new{revision="R995",utc=DateTime.UtcNow.ToString("o"),qpc=Stopwatch.GetTimestamp(),qpc_frequency=Stopwatch.Frequency,os=Environment.OSVersion.VersionString,clr=Environment.Version.ToString(),process64=Environment.Is64BitProcess,files=files,scope="Collector software identity at export time; launch.json records actual run software separately. Only app/model manifest identity. No account, global environment, input, screenshots or full memory collected."};}
  static Dictionary<string,object> ReadObject(string path){try{if(!File.Exists(path)||new FileInfo(path).Length>PerFile)return null;return Json().DeserializeObject(File.ReadAllText(path)) as Dictionary<string,object>;}catch{return null;}}
  static object Value(Dictionary<string,object> o,string k){object v;return o!=null&&o.TryGetValue(k,out v)?v:null;}
  public static void DecodeNative(string appRoot,string directory){
   string input=Path.Combine(directory,"app-flight994.bin"),output=Path.Combine(directory,"app-flight994.decoded.jsonl"),tool=Path.Combine(appRoot,"diag-export994.exe");
   if(!File.Exists(input))return;try{Guard(directory);if(!File.Exists(tool))throw new FileNotFoundException("Native diagnostic decoder is missing");
    if(input.Contains("\"")||output.Contains("\""))throw new IOException("Invalid diagnostic path");
    var psi=new ProcessStartInfo(tool,"\""+input+"\" \""+output+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=directory};
    using(var p=Process.Start(psi)){if(!p.WaitForExit(10000)){p.Kill();p.WaitForExit(1000);throw new TimeoutException("CPU-only native recorder decode exceeded 10 seconds");}if(p.ExitCode!=0)throw new IOException("Native decoder exit "+p.ExitCode);}
   }catch(Exception e){try{File.WriteAllText(Path.Combine(directory,"decoder-failure994.json"),Serialize(new{schema=1,error=e.GetType().Name,hresult=e.HResult,message=Redact(e.Message,appRoot),raw_preserved=true}),new UTF8Encoding(false));}catch{}Record(appRoot,"diagnostics.decode_failed","warning",null,e);}
  }
  public static void Analyze(string directory){
   try{Guard(directory);var findings=new List<object>();var missing=new List<string>();
    foreach(var name in new[]{"app-processing992.json","app-output993.json","app-telemetry-shutdown993.json","app-commit700.json","app-lifecycle988.json","startup-verification.json"})if(!File.Exists(Path.Combine(directory,name)))missing.Add(name);
    var lifecycle=ReadObject(Path.Combine(directory,"app-lifecycle988.json"));var commit=ReadObject(Path.Combine(directory,"app-commit700.json"));var telemetry=ReadObject(Path.Combine(directory,"app-telemetry-shutdown993.json"));
    if(commit!=null){findings.Add(new{code="generation.accounting",evidence="app-commit700.json",confidence="recorded",data=commit,interpretation="Completed/submitted are not optical display proof. Compare lifecycle cancellation before calling the difference a lost frame."});}
    if(lifecycle!=null)findings.Add(new{code="lifecycle.cancellation",evidence="app-lifecycle988.json",confidence="recorded",data=lifecycle,interpretation="Pause and stop cancellation keep their energy cost and are excluded from successful generated display."});
    if(telemetry!=null)findings.Add(new{code="telemetry.shutdown",evidence="app-telemetry-shutdown993.json",confidence="recorded",data=telemetry,interpretation="A blocked query identifies the outstanding stage, not the cause inside a driver."});
    string engine=Path.Combine(directory,"app-engine.log");var relevant=new List<object>();if(File.Exists(engine)){int line=0;using(var reader=new StreamReader(new FileStream(engine,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)))for(string text;(text=reader.ReadLine())!=null;){line++;if(text.IndexOf("device lost",StringComparison.OrdinalIgnoreCase)>=0||text.IndexOf("device removed",StringComparison.OrdinalIgnoreCase)>=0||text.IndexOf("timeout",StringComparison.OrdinalIgnoreCase)>=0||text.IndexOf("terminating",StringComparison.OrdinalIgnoreCase)>=0||text.IndexOf("exception",StringComparison.OrdinalIgnoreCase)>=0){if(relevant.Count==128)relevant.RemoveAt(0);relevant.Add(new{line=line,text=Limit(text)});}}}
    var nativeEvidence=new List<object>();var nativeFailures=new List<object>();long nativeFailureCount=0;string decoded=Path.Combine(directory,"app-flight994.decoded.jsonl");if(File.Exists(decoded)&&new FileInfo(decoded).Length<32*1024*1024){using(var reader=new StreamReader(decoded)){int malformed=0;for(string text;(text=reader.ReadLine())!=null;){try{var row=Json().DeserializeObject(text) as Dictionary<string,object>;string type=Convert.ToString(Value(row,"type"));if((type=="summary"||type=="crash"||type=="open_begin")&&nativeEvidence.Count<512)nativeEvidence.Add(row);if(type=="event"&&(Convert.ToString(Value(row,"action"))=="fail"||Convert.ToString(Value(row,"action"))=="abort")){nativeFailureCount++;if(nativeFailures.Count==256)nativeFailures.RemoveAt(0);nativeFailures.Add(row);}}catch{malformed++;}}if(malformed>0)nativeEvidence.Add(new{type="decode_parse_errors",count=malformed});}}
    var metadata=new Dictionary<string,object>();foreach(string name in new[]{"app-device994.json","app-vulkan-queues994.json","app-d3d-device994.json","app-bridge-adapter994.json","app-model994.json"}){var data=ReadObject(Path.Combine(directory,name));if(data!=null)metadata[name]=data;else missing.Add(name);}
    var summary=new{schema=1,revision="R995",native_metadata=metadata,native_evidence=nativeEvidence,native_failure_events=nativeFailures,native_failure_count=nativeFailureCount,native_failure_index_truncated=nativeFailureCount>256,created_utc=DateTime.UtcNow.ToString("o"),scope="Evidence index, not an automatic root-cause verdict",findings=findings,error_log_candidates=relevant,missing_files=missing,processing=ReadObject(Path.Combine(directory,"app-processing992.json")),output=ReadObject(Path.Combine(directory,"app-output993.json")),limitations=new[]{"No GPU kernel crash dump or internal driver stack is available from these application breadcrumbs.","An unmatched begin means no completed record was retained; a process may have stopped or the ring may have overwritten its match.","No error entry is not proof of no error; inspect dropped/truncated counters and crash-recorder coverage.","Power domains are not frame-generation incremental power; Present is not physical scanout.","Pixel corruption and temporal quality require a separately authorized recording; no pixels are collected by default."}};
    File.WriteAllText(Path.Combine(directory,"diagnosis-summary994.json"),Serialize(summary),new UTF8Encoding(false));
    File.WriteAllText(Path.Combine(directory,"READ-DIAGNOSTICS.zh-CN.txt"),"先看 diagnosis-summary994.json，再按证据文件、帧/任务号与 QPC 对齐。\r\nlaunch.json 是当次启动配置；不要用后来保存的 settings.json 代替。\r\napp-flight994.bin 是有界崩溃前记录（内含崩溃槽）；app-flight994.decoded.jsonl 是解码后的时间线。\r\n原始 HRESULT/VkResult、队列与 fence 证据用于区分捕获、提交、等待和显示问题。最后未完成的调用不是已证实的根因。\r\n日志缺失、截断、环覆盖与导出失败都必须纳入结论；不把未知写成正常。\r\n默认不包含截图、键鼠输入、完整进程内存，也不自动上传。Windows 驱动内核内部错误可能仍需厂商支持。\r\n",new UTF8Encoding(false));
   }catch(Exception e){try{File.WriteAllText(Path.Combine(directory,"diagnosis-summary-failure994.json"),Serialize(new{error=e.GetType().Name,hresult=e.HResult,message=Limit(e.Message)}));}catch{}}
  }
  static readonly HashSet<string> DiagnosticFiles994=new HashSet<string>("app-capabilities995.jsonl app-device994.json app-vulkan-queues994.json app-d3d-device994.json app-bridge-adapter994.json app-model994.json app-acceptance695.json app-actual-config653.json app-admissions988.csv app-arrivals.csv app-async905.csv app-budget.csv app-budget.json app-capture.csv app-capture838.json app-claimed-recovery988.json app-claims988.csv app-commit700.json app-completion-start988.json app-copy-stages988.csv app-copy926.csv app-deadline664.json app-display-prepare988.json app-display-priority988.json app-display988.csv app-dxgi-config988.json app-engine.log app-gpuqueue960.json app-hud988.jsonl app-job-inputs933.csv app-lifecycle988.csv app-lifecycle988.json app-live775.json app-log-budget989.json app-natural-end988.json app-node-map830.csv app-observed-output.json app-opaque-content988.json app-original-recovery988.csv app-original-recovery988.json app-output-balance.json app-output993.json app-pacing.json app-passthrough.json app-phase971.csv app-phase971.json app-prediction930.csv app-preparation-stages992.jsonl app-preparation862.json app-present.csv app-producer933.csv app-processing992.json app-profile.json app-ready809.csv app-ready912.csv app-recovery-window988.json app-recovery809.json app-requested-effective988.json app-session.json app-stages931.csv app-startup775.json app-sustained-recovery988.json app-target-process993.jsonl app-telemetry-shutdown993.json app-timeline.json app-ui-checks.json app-window-events.csv app-window-state990.jsonl app-window795.json app-window976.jsonl startup-verification.json archive-result.json desktop-events994.jsonl desktop-events994.jsonl.previous desktop.log capture-picker991.json launch.json engine-exit.json app-flight994.bin app-crash994.bin app-flight994.decoded.jsonl".Split(' '),StringComparer.OrdinalIgnoreCase);
  static bool AllowedFile994(string name){return DiagnosticFiles994.Contains(name)||((name.StartsWith("app-diag",StringComparison.Ordinal)||name.StartsWith("app-diagnostic",StringComparison.Ordinal))&&(name.EndsWith("994.json",StringComparison.Ordinal)||name.EndsWith("994.jsonl",StringComparison.Ordinal)));}
  static bool IsText(string path){string e=Path.GetExtension(path).ToLowerInvariant();return e==".json"||e==".jsonl"||e==".log"||e==".csv"||e==".txt"||e==".md"||e==".previous";}
  public static string Export(string appRoot,string sessionDir,string archiveDirectory,bool live){
   if(live)throw new InvalidOperationException("Export requires a stopped immutable archive; live recording continues independently.");
   if(String.IsNullOrEmpty(archiveDirectory)||!Directory.Exists(archiveDirectory)||!File.Exists(Path.Combine(archiveDirectory,"archive-result.json")))throw new IOException("No immutable session archive. Mutable work logs were not substituted.");
   Guard(archiveDirectory);
   string data=Path.Combine(appRoot,"UserData"),exports=Path.Combine(data,"diagnostics");Guard(exports);Directory.CreateDirectory(exports);
   string id=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8);string staging=Path.Combine(exports,"export-"+id);Directory.CreateDirectory(staging);
   var manifest=new List<object>();var candidates=new List<KeyValuePair<string,string>>();
   foreach(var n in new[]{"desktop-events994.jsonl","desktop-events994.jsonl.previous","desktop.log","capture-picker991.json"}){string p=Path.Combine(data,n);if(File.Exists(p))candidates.Add(new KeyValuePair<string,string>(p,n));}
   if(!String.IsNullOrEmpty(sessionDir)&&Directory.Exists(sessionDir)){string launch=Path.Combine(sessionDir,"launch.json");if(File.Exists(launch))candidates.Add(new KeyValuePair<string,string>(launch,"launch.json"));string exit=Path.Combine(sessionDir,"engine-exit.json");if(File.Exists(exit))candidates.Add(new KeyValuePair<string,string>(exit,"engine-exit.json"));}
   string source=archiveDirectory;
   foreach(string file in Directory.GetFiles(source,"app-*",SearchOption.TopDirectoryOnly))candidates.Add(new KeyValuePair<string,string>(file,Path.GetFileName(file)));
   foreach(var n in new[]{"startup-verification.json","archive-result.json"}){string file=Path.Combine(source,n);if(File.Exists(file))candidates.Add(new KeyValuePair<string,string>(file,n));}
   long total=0;int count=0;var stopwatch=Stopwatch.StartNew();
   foreach(var item in candidates.OrderBy(x=>x.Key.EndsWith(".bin")?0:x.Key.EndsWith(".json")?1:2)){
    string file=item.Key,name=item.Value;string dest=Path.Combine(staging,name);try{
    if(!AllowedFile994(name)){manifest.Add(new{file=name,status="excluded_not_diagnostic"});continue;}
    Guard(file);if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException("Reparse log rejected");long bytes=new FileInfo(file).Length;if(bytes>PerFile||total+bytes>BundleLimit||++count>256||stopwatch.ElapsedMilliseconds>15000){manifest.Add(new{file=name,status="omitted_limit",source_bytes=bytes});continue;}
     if(File.Exists(dest)){manifest.Add(new{file=name,status="duplicate_name_skipped"});continue;}
     using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var output=new FileStream(dest,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){byte[] buffer=new byte[65536];long remaining=bytes;while(remaining>0){int n=input.Read(buffer,0,(int)Math.Min(remaining,buffer.Length));if(n==0)break;output.Write(buffer,0,n);remaining-=n;}if(remaining!=0)throw new IOException("Source shortened during snapshot");}
     if(IsText(file)){
      string text=Redact(File.ReadAllText(dest),appRoot);
      if(name=="launch.json"){var launch=Json().DeserializeObject(text) as Dictionary<string,object>;var profile=Value(launch,"Settings") as Dictionary<string,object>;if(profile!=null){profile["Name"]="<profile>";profile["Filter"]="<redacted>";}text=Serialize(launch);}
      File.WriteAllText(dest,text,new UTF8Encoding(false));
     }
     long copied=new FileInfo(dest).Length;total+=copied;manifest.Add(new{file=name,status="copied",source_bytes=bytes,export_bytes=copied,sha256=Hash(dest),snapshot_not_atomic=live});
    }catch(Exception e){if(File.Exists(dest))File.Delete(dest);manifest.Add(new{file=name,status="failed",error=e.GetType().Name,hresult="0x"+e.HResult.ToString("X8"),message=Redact(Limit(e.Message),appRoot)});}
   }
   DecodeNative(appRoot,staging);Analyze(staging);File.WriteAllText(Path.Combine(staging,"software-identity994.json"),Serialize(SoftwareIdentity(appRoot)),new UTF8Encoding(false));
   var finalFiles=Directory.GetFiles(staging).Select(file=>new{name=Path.GetFileName(file),bytes=new FileInfo(file).Length,sha256=Hash(file)}).ToArray();
   File.WriteAllText(Path.Combine(staging,"bundle-manifest994.json"),Serialize(new{schema=1,revision="R995",created_utc=DateTime.UtcNow.ToString("o"),live_snapshot=live,archive_id=Path.GetFileName(archiveDirectory),session_id=String.IsNullOrEmpty(sessionDir)?null:Path.GetFileName(sessionDir),host_events_scope="Host events may span runs; correlate recorded session IDs and UTC/QPC, not archive membership alone.",total_bytes=finalFiles.Sum(x=>x.bytes),source_files=manifest,files=finalFiles,max_file_bytes=PerFile,max_source_snapshot_bytes=BundleLimit,managed_recording_dropped_events=Interlocked.Read(ref dropped),redaction="App and user-profile paths replaced; profile name/filter removed. Other selected-game names and timings remain. Review before sharing.",privacy="Local only. No screenshots, keyboard/controller input, credentials, full memory or automatic network upload.",completeness="See every per-file status; live snapshots may contain an incomplete final record."}),new UTF8Encoding(false));
   string zip=Path.Combine(exports,"SmoothMotion-diagnostics-"+id+".zip");ZipFile.CreateFromDirectory(staging,zip,CompressionLevel.Fastest,false);
   foreach(string file in Directory.GetFiles(staging))File.Delete(file);Directory.Delete(staging);Record(appRoot,"diagnostics.exported","info",new{file=Path.GetFileName(zip),live=live,bytes=new FileInfo(zip).Length});return zip;
  }
